def minimum_end_deletions_for_equal_strings(s1,s2,s3):
    common=0
    for a,b,c in zip(s1,s2,s3):
        if a!=b or b!=c:break
        common+=1
    return -1 if common==0 else len(s1)+len(s2)+len(s3)-3*common

